package lk.smartroute.service.impl;
import com.google.zxing.*;import com.google.zxing.client.j2se.MatrixToImageWriter;import com.google.zxing.common.BitMatrix;import lk.smartroute.dto.ApiDtos.QrTicketResponse;import lk.smartroute.exception.*;import lk.smartroute.model.*;import lk.smartroute.repository.BookingRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.io.*;import java.time.LocalDateTime;import java.util.Base64;
@Service public class TicketQrService { private final BookingRepository bookings; public TicketQrService(BookingRepository bookings){this.bookings=bookings;}
 @Transactional(readOnly=true) public QrTicketResponse generate(String email,Long id,boolean staff){Booking b=bookings.findById(id).orElseThrow(()->new ResourceNotFoundException("Booking not found"));if(!staff&&!b.getPassenger().getUser().getEmail().equalsIgnoreCase(email))throw new ForbiddenActionException("Booking does not belong to user");if(b.getBookingStatus()!=BookingStatus.CONFIRMED&&b.getBookingStatus()!=BookingStatus.COMPLETED)throw new IllegalStateException("QR ticket is available after payment");try{String seats=b.getBookingSeats().stream().map(x->String.valueOf(x.getSeat().getSeatNumber())).sorted().reduce((a,c)->a+","+c).orElse("");String payload="SMARTROUTE|BOOKING="+b.getBookingReference()+"|SEATS="+seats;BitMatrix matrix=new MultiFormatWriter().encode(payload,BarcodeFormat.QR_CODE,320,320);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matrix,"PNG",out);return new QrTicketResponse(b.getBookingReference(),"data:image/png;base64,"+Base64.getEncoder().encodeToString(out.toByteArray()),LocalDateTime.now());}catch(Exception e){throw new IllegalStateException("Unable to generate QR ticket",e);}}
}
